const store = globalThis as unknown as { notificationsEnabled?: boolean }

if (store.notificationsEnabled === undefined) {
  store.notificationsEnabled = false
}

export function getNotificationsEnabled(): boolean {
  return store.notificationsEnabled as boolean
}

export function setNotificationsEnabled(value: boolean): void {
  store.notificationsEnabled = value
}

