args.content:
import { toggleNotificationPreference } from '@/app/actions'
import { getNotificationsEnabled } from '@/app/lib/preferences'

export default function Home() {
  const enabled = getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? 'ON' : 'OFF'}.</p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

